WITH filtered AS (SELECT *, UPPER(status) AS status_upper FROM orders WHERE order_date >= DATE '2023-04-02' AND store_id IS NOT NULL), enriched AS (SELECT *, AVG(discount) OVER (ORDER BY discount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS discount_avg_6, LEAD(discount, 2) OVER (ORDER BY shipping_fee, id) AS next_discount FROM filtered), kept_keys AS (SELECT store_id, channel FROM enriched EXCEPT ALL SELECT store_id, channel FROM orders WHERE amount <= 1570), kept_rows AS (SELECT s.* FROM enriched s INNER JOIN kept_keys k ON s.store_id = k.store_id AND s.channel = k.channel), base AS (SELECT *, amount + shipping_fee AS amount_with_shipping FROM kept_rows WHERE status = 'SHIPPED'), metrics AS (SELECT id, status, channel, amount, discount, shipping_fee, status_upper, PERCENT_RANK() OVER w_grp AS amount_with_shipping_percent_rank, DENSE_RANK() OVER w_grp_2 AS discount_dense_rank, CORR(shipping_fee, discount) OVER (PARTITION BY status) AS corr_shipping_fee_discount FROM base WHERE next_discount > 0.15 WINDOW w_grp AS (PARTITION BY store_id ORDER BY amount_with_shipping DESC), w_grp_2 AS (PARTITION BY store_id, status ORDER BY discount NULLS LAST)), with_windows AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY status), 4) AS amount_share FROM metrics), eligible AS (SELECT s.* FROM with_windows s WHERE EXISTS (SELECT 1 FROM payments c WHERE c.order_id = s.id AND c.order_id IN (5, 6, 22))) SELECT channel, status, STDDEV_SAMP(discount) AS discount_stddev, STDDEV_SAMP(amount) AS amount_stddev FROM eligible GROUP BY CUBE (channel, status) HAVING discount_stddev > 0 ORDER BY discount_stddev NULLS LAST;
